use qop_wire::*;
use ed25519_dalek::SigningKey;
#[test]fn wire_and_mmr(){let k=SigningKey::from_bytes(&[7;32]);let p=[9;24];let mut l=Ledger::new(k.verifying_key(),p);let mut prev=GENESIS;let mut frames=vec![];for i in 0..10000u64{let f=mint(&k,i,i*10,i*10+5,(i%3+1)as u32,[8;32],prev,p);assert_eq!(f.len(),256);assert!(l.append(&f));prev.copy_from_slice(&f[104..136]);frames.push(f);if i<64{for j in 0..=i as usize{assert!(verify_proof(&frames[j],&l.mmr.proof(j).unwrap(),&k.verifying_key(),&p,l.mmr.root(),l.mmr.len()));}}}for j in [0,1,4321,8191,8192,9999]{let proof=l.mmr.proof(j).unwrap();assert!(verify_proof(&frames[j],&proof,&k.verifying_key(),&p,l.mmr.root(),10000));assert!(proof.siblings.len()+proof.other_peaks.len()<=26);assert!(!verify_proof(&frames[j],&proof,&k.verifying_key(),&p,[0;32],10000));let mut bad=proof.clone();bad.index^=1;assert!(!verify_proof(&frames[j],&bad,&k.verifying_key(),&p,l.mmr.root(),10000));assert!(!verify_proof(&frames[j],&proof,&k.verifying_key(),&p,l.mmr.root(),9999));}assert!(!l.append(&frames[0]));println!("10000 signed frames; checkpoint {}",hex::encode(l.mmr.root()));}
#[test]fn rejects(){let k=SigningKey::from_bytes(&[7;32]);let p=[9;24];let mut l=Ledger::new(k.verifying_key(),p);let f=mint(&k,0,10,20,2,[8;32],GENESIS,p);for i in [0,8,16,24,32,36,40,72,104,136,160,192,255]{let mut b=f;b[i]^=1;assert!(!l.append(&b));}assert!(!l.append(&mint(&k,1,10,20,1,[8;32],GENESIS,p)));assert!(!l.append(&mint(&k,0,20,10,1,[8;32],GENESIS,p)));assert!(!l.append(&mint(&k,0,10,20,4,[8;32],GENESIS,p)));assert!(!l.append(&mint(&SigningKey::from_bytes(&[3;32]),0,10,20,1,[8;32],GENESIS,p)));assert!(l.append(&f));assert!(!l.append(&mint(&k,1,19,30,1,[8;32],f[104..136].try_into().unwrap(),p)));assert!(!l.append(&mint(&k,1,20,30,1,[8;32],GENESIS,p)));assert!(json(&f).contains("\"process_seq\":\"0\""));}
